def rd(name, dur=0.5):
    fd = os.open('/dev/robot/'+name, os.O_RDONLY | os.O_NONBLOCK)
    out=[]
    t0=time.time()
    while time.time()-t0<dur:
        r,_,_=select.select([fd],[],[],0.05)
