                    log("CMD "+L+" -> "+json.dumps(res)[:400])
                except Exception as e:
                    log("CMD ERR "+L+" : "+repr(e))
                    stop()
    except Exception as e:
        log("cmdfile err "+repr(e))
    if i%60==0:
        json.dump(state,open('/memory/state.json','w'))
stop(); log("pilot exited")
